  images: ["images/104_1.jpg"],
  introText: "أعلنت جماعات إقليم إفران، بناءً على القرار المشترك رقم 01 بتاريخ 06 أبريل 2026، عن تنظيم مباريات مشتركة لتوظيف 112 تقنياً موزعين بين 52 تقنياً من الدرجة الرابعة (السلم 8) و60 تقنياً من الدرجة الثالثة (السلم 9). تهدف هذه التوظيفات إلى دعم المصالح التقنية لمختلف جماعات الإقليم بكفاءات شابة ومؤهلة قادرة على المساهمة في تنفيذ وتتبع مشاريع التنمية المحلية. تشمل التخصصات المطلوبة مجالات حيوية كالهندسة المدنية والأشغال العمومية والإعلاميات والكهرباء والميكانيك، مما يفتح الباب أمام خريجي التكوين المهني وحملة الدبلومات التقنية للانضمام إلى قطاع الإدارة الترابية. [0†L4-L11]",
  description: "توظيف 112 تقنياً (52 من الدرجة الرابعة و60 من الدرجة الثالثة) في عدة تخصصات لفائدة جماعات إقليم إفران.",
  mission: "سيتولى التقنيون الجدد مسؤولية إعداد وتتبع مشاريع البناء والأشغال العمومية، وإجراء الدراسات التقنية اللازمة، ومراقبة جودة الأشغال وضمان مطابقتها للمعايير، وصيانة الأنظمة المعلوماتية والشبكات، وتركيب وصيانة التجهيزات الكهربائية والميكانيكية، بالإضافة إلى قيادة وصيانة العربات وآليات الأشغال الكبرى.",
  lieu: "مختلف جماعات إقليم إفران (تيمحضيت، واد إفران، سيدي المخفي، أزرو، إفران، ضاية عوا، تكريكرة، تزكيت، عين اللوح، بن صميم).", 
  ageLimit: "18 إلى 40 سنة كحد أقصى (يمكن التمديد إلى 45 سنة لفئات خاصة)", 
