  specialites: "للسلم 9 (60 منصب): الهندسة المدنية، الأشغال الكبرى، صيانة الأنظمة المعلوماتية. السلم 8 (52 منصب): الهندسة المدنية، الإعلاميات، السياقة، الميكانيك، الكهرباء. [5†L8-L12][6†L8-L12]",
