  introText: "أعلنت وزارة التربية الوطنية والتعليم الأولي والرياضة عن تنظيم مباريات ولوج المراكز الجهوية لمهن التربية والتكوين (CRMEF) لتوظيف 442 أستاذاً للتعليم الابتدائي من الدرجة الثانية (السلم 10). تهدف هذه المباريات إلى تكوين جيل جديد من المعلمين المؤهلين للارتقاء بجودة التعليم بالمدرسة الابتدائية المغربية.",
