  postes: 440,
  datePub: "2026-04-13",
  deadline: "2026-04-28T16:30:00",
  image: "images/303_1.jpg",
  introText: "أعلنت وزارة الداخلية عن تنظيم مباراة كبرى لتوظيف 440 متصرفاً من الدرجة الثانية، وذلك في إطار تعزيز مواردها البشرية ودعم كفاءاتها الإدارية والتقنية. تستهدف هذه المباراة الحاصلين على شهادات الماستر في تخصصات القانون والتدبير، وهي تمثل فرصة ذهبية للشباب المغربي للالتحاق بأحد أكثر القطاعات حيوية واستقراراً في الوظيفة العمومية. تهدف الوزارة من خلال هذه المبادرة إلى استقطاب كفاءات مؤهلة قادرة على مواكبة التحديات المرتبطة بتحديث الإدارة الترابية وتحسين جودة الخدمات العمومية.",
  description: "وزارة الداخلية تعلن عن توظيف 440 متصرفاً من الدرجة الثانية في تخصصات القانون والتدبير.",
  mission: "سيتولى المتصرفون الجدد القيام بمهام إدارية وتدبيرية متخصصة داخل المصالح المركزية والترابية لوزارة الداخلية. تشمل هذه المهام تنفيذ السياسات العمومية على المستوى المحلي، والإشراف على الشؤون الإدارية والمالية للعمالات والأقاليم، وضمان التنسيق بين مختلف المصالح اللاممركزة. كما سيكونون مسؤولين عن تدبير الموارد البشرية والمالية، والمساهمة في إعداد وتنفيذ الميزانيات، وتقديم الاستشارة القانونية والإدارية اللازمة لضمان السير العادي للمرافق العمومية التابعة للوزارة. بالإضافة إلى ذلك، سيشاركون في عمليات الافتحاص ومراقبة التسيير، والمساهمة في تحديث الإدارة وتطوير أساليب العمل.",
