  diplome: "شهادة الماستر أو الماستر المتخصص، دبلوم الدراسات العليا المعمقة (DESA)، أو دبلوم الدراسات العليا المتخصصة (DESS).",
  specialites: "القانون الإداري وعلم الإدارة، التدبير المالي والمحاسباتي أو الإفتحاص ومراقبة التسيير، القانون العام (باللغة الفرنسية).",
