  apresTest: "يتم الإعلان عن النتائج النهائية عبر الموقع الإلكتروني للمكتب الوطني للسكك الحديدية. المقبولون يستفيدون من برنامج تكويني وتأهيلي (Onboarding) قبل التعيين الرسمي في مختلف المواقع التابعة للمكتب عبر التراب الوطني. يوفر المكتب للموظفين الجدد بيئة عمل محفزة ومساراً مهنياً متطوراً وبرامج تكوين مستمر.",
