  mission: "سيتولى المتصرفون الجدد مهام متنوعة حسب تخصصاتهم. سيعمل المتخصصون في الجيولوجيا والتنقيب على دراسة وتقييم الموارد المعدنية والمساهمة في مشاريع التنقيب. بينما سيشرف المتخصصون في التدقيق ومراقبة التسيير والتدبير المالي على تحليل وتدقيق الحسابات وضمان الامتثال المالي والإداري. أما المتخصصون في الإعلاميات والميكاترونيك، فسيساهمون في تطوير وصيانة الأنظمة المعلوماتية والتقنية للوزارة. بشكل عام، سيساهم الجميع في تنفيذ السياسات العمومية للقطاع، وإعداد التقارير الاستراتيجية، وضمان التنسيق بين مختلف المصالح.",
