  mission: "سيتولى مهندسو الدولة الجدد القيام بمهام تقنية وتدبيرية متخصصة داخل المصالح التقنية للمكتب الجهوي للاستثمار الفلاحي للغرب. تشمل هذه المهام إعداد وتنفيذ وتتبع مشاريع الهندسة المدنية المتعلقة بالبنيات التحتية الفلاحية (السواقي، المسالك، السدود الصغيرة)، والإشراف على دراسات الهندسة القروية ومشاريع الري وصرف المياه. كما سيعمل مهندس الطوبوغرافيا على القيام بعمليات الرفع والمسح الطوبوغرافي للمناطق الفلاحية. أما مهندس المعلوميات، فسيساهم في تطوير وصيانة الأنظمة المعلوماتية للمكتب، وتطوير حلول رقمية لتحسين التدبير الفلاحي. سيساهم الجميع في إعداد دفاتر التحملات والمواصفات التقنية، ومواكبة المقاولات في تنفيذ المشاريع، وتقديم الخبرة التقنية اللازمة لتطوير القطاع الفلاحي بالمنطقة.",
