  description: "توظيف 16 إطاراً في تخصصات الإشراف البنكي، المراقبة الداخلية، وتطوير المالية الرقمية ببنك المغرب.",
  mission: "يضطلع بنك المغرب بمهام سيادية متعددة تشمل: إصدار النقود وتدبير الأوراق النقدية والقطع المعدنية المتداولة، وإعداد وتنفيذ السياسة النقدية الرامية إلى استقرار الأسعار، والإشراف على السوق النقدي ومراقبة الأنشطة المالية وتنظيمها، وتدبير احتياطيات الصرف والحفاظ على قيمتها وسيولتها، ومراقبة البنوك والحفاظ على استقرار وكفاءة المؤسسات المالية، والمساهمة في الاستقرار المالي وخلق بيئة اقتصادية متينة ومستدامة، وتعزيز أمن وموثوقية المدفوعات. كما يضطلع البنك بمهام استشارية لفائدة الحكومة في المجالين الاقتصادي والمالي، ويعمل كوكيل للخزينة العامة للمملكة في العمليات البنكية الوطنية والدولية.",
