  centreMabara: "الرباط (المقر الرئيسي لبنك المغرب)",
  epreuves: "تشمل عملية الانتقاء عدة مراحل: 1. الانتقاء الأولي: دراسة الملفات والتأكد من استيفائها للشروط المطلوبة. 2. اختبار كتابي: يتضمن أسئلة في التخصص المطلوب ومواضيع ذات صلة بالمجال المالي والمصرفي (المدة: 3 ساعات، المعامل: 3). 3. اختبار شفوي: مقابلة أمام لجنة مختصة لتقييم القدرات التحليلية والتواصلية للمترشح ومدى إلمامه بمجال الإشراف البنكي أو المراقبة الداخلية أو المالية الرقمية (المدة: 20-30 دقيقة، المعامل: 2). يتم الإعلان عن النتائج بعد كل مرحلة عبر الموقع الرسمي لبنك المغرب.",
  apresTest: "يتم الإعلان عن النتائج النهائية عبر الموقع الرسمي لبنك المغرب (www.bkam.ma). المقبولون يستفيدون من برنامج تكويني متطور داخل البنك ويتم تعيينهم في مناصبهم بالمقر الرئيسي بالرباط. يوفر بنك المغرب للموظفين الجدد نظاماً تحفيزياً يشمل تعويضات تنافسية وبرامج تكوين مستمر وتأميناً صحياً ومساراً مهنياً متطوراً داخل المؤسسة.",
