  carriere: "يُعتبر منصب متصرف بوزارة التضامن منصباً محورياً لتنفيذ السياسات الاجتماعية. بعد الترسيم، يمكن للمتصرف الترقية إلى درجة متصرف من الدرجة الأولى بعد 4 سنوات من الخدمة الفعلية (بالنسبة لخريجي الماستر)، ثم إلى درجة متصرف ممتاز. توفر الوزارة أيضاً برامج تكوين مستمر في مجالات الحماية الاجتماعية وتدبير المشاريع التنموية، مما يفتح آفاقاً مهنية واسعة في قطاع العمل الاجتماعي."
