  epreuves: "تتكون المباراة من مرحلتين: 1. اختبار كتابي في التخصص والمجالات المرتبطة به (ساعتان إلى ثلاث ساعات، معامل 3). 2. اختبار شفوي للمترشحين الحاصلين على معدل 12/20 على الأقل في الاختبار الكتابي (مناقشة مع لجنة حول مواضيع تقنية وعامة). يعتبر كل اختبار نهائياً، وتقتصر لائحة الناجحين على عدد المقاعد المتبارى في شأنها.",
  apresTest: "سيتم الإعلان عن النتائج عبر بوابة التشغيل العمومي والموقع الرسمي لوزارة الداخلية. المقبولون سيتابعون تكويناً متخصصاً في معاهد تابعة لوزارة الداخلية قبل تعيينهم في مختلف الجماعات الترابية. يعتبر النجاح في التكوين شرطاً أساسياً للتعيين.",
