  carriere: "يُعتبر هذا المسار من أفضل المسارات للتقنيين في المغرب. بعد النجاح في المباراة، ستتابع تكويناً متخصصاً في معاهد وزارة الداخلية (مدة التكوين سنتان). خلال التكوين، تستفيد من منحة شهرية وتغطية اجتماعية. بعد التخرج، يتم تعيينك مباشرة في إحدى الجماعات الترابية (جماعة حضرية أو قروية) برتبة تقني من الدرجة الثالثة (سلم 9). المسار الوظيفي يسمح بالترقية إلى درجة تقني من الدرجة الثانية بعد 6 سنوات من الخدمة الفعلية. كما يمكنك متابعة تكوينات إضافية للتخصص في مجالات دقيقة كالأمن السيبراني أو إدارة المشاريع الرقمية."
