    "أن يكون حاصلاً على دبلوم تقني في النقل والإسعاف الصحي أو شهادة معادلة.",
    "التوفر على رخصة سياقة صالحة (غالباً صنف C أو D).",
    "أن يستوفي شروط اللياقة البدنية والصحة الجيدة اللازمة لمزاولة المهمة."
