  epreuves: "تشتمل المباراة على: 1. اختبار كتابي في التخصص (3 ساعات، المعامل 3): أسئلة تطابق مستوى تقني من الدرجة الرابعة في النقل والإسعاف الصحي. 2. اختبار عام في التحليل والترجمة (3 ساعات، المعامل 2): يشمل تلخيص نص بالعربية أو الفرنسية والتعليق عليه، وترجمة الملخص إلى اللغة الأخرى. 3. اختبار شفوي (15-20 دقيقة، المعامل 2): يتعلق بالثقافة العامة والتخصص. النجاح يستوجب الحصول على 12/20 كمعدل عام دون نقطة إقصائية (أقل من 5/20).",
