  apresTest: "بعد إجراء الاختبارات، تنشر نتائج الاختبار الكتابي والنتائج النهائية، بما في ذلك لائحة الانتظار، على بوابة التشغيل العمومي www.emploi-public.ma، كما يمكن تعميمها ونشرها بكل الوسائل المتاحة. إذا ثبت أن مترشحاً سبق أن أعلن عن نجاحه لا يتوفر على واحد أو أكثر من الشروط المطلوبة أو أدلى بمعلومات غير صحيحة، سيتم تعويضه بمترشح آخر مرتب حسب الاستحقاق في لائحة الانتظار يستوفي هذه الشروط. يتم تعيين الناجحين النهائيين كمتمرنين لفترة تدريبية قبل الترسيم في الدرجة.",
  inscriptionDebut: "2026-05-20",
