    "الحصول، وجوباً عند تسجيل الترشيح، على شهادة مهندس دولة في الهندسة البيوطبية (Génie biomédical)، المسلمة من طرف المدارس أو المعاهد أو المؤسسات الجامعية الوطنية المؤهلة لتسليمها، أو على إحدى الشهادات المعادلة لها.",
    "التوفر على تجربة مهنية لا تقل عن أربع سنوات في إحدى مصالح الهندسة الطبية الحيوية.",
    "التوفر على القدرات البدنية والذهنية اللازمة لممارسة المهام.",
    "بالنسبة للموظفين: موافقة نهائية من الإدارة التي ينتمون إليها (المصالح المكلفة بالموارد البشرية)."
