  introText: "أعلنت المديرية الجهوية لوزارة الصحة والحماية الاجتماعية بجهة درعة تافيلالت عن تنظيم مباراة توظيف كبرى تشمل 600 منصباً في الدرجة الأولى (السلم 10) ضمن أطر هيئة الممرضين وتقنيي الصحة. تأتي هذه المباراة في إطار تعزيز المنظومة الصحية بالجهة، وتلبية الاحتياجات المتزايدة من الكفاءات الطبية والشبه طبية. سيتم إجراء المباراة يوم الأحد 28 يونيو 2026 بمدينة الرشيدية، وسيظل باب الترشيح مفتوحاً إلى غاية 23 يونيو 2026، مما يتيح فرصة استثنائية لخريجي المعاهد العليا للمهن التمريضية للانضمام إلى القطاع الصحي العمومي بجهة درعة تافيلالت.",
