  mission: "تتمثل المهام الرئيسية للممرضين في تقديم العلاجات التمريضية، والمشاركة في أنشطة التوعية والتربية الصحية، وتقديم خدمات الرعاية الصحية الأولية، والمساهمة في أنشطة الصحة المدرسية والجامعية، والمشاركة في برامج الصحة الجماعاتية، والإسعاف والمساعدة الطبية الاستعجالية. تشمل المباراة خمسة أطر رئيسية: إطار الممرضين، إطار تقنيي الصحة، إطار المروضين، إطار القابلات، وإطار المساعدين في المجال الطبي الاجتماعي.",
