  centreMabara: "الرشيدية (جهة درعة تافيلالت)",
  epreuves: "تشتمل المباراة على اختبارين: 1. اختبار كتابي (المدة: ساعتان، المعامل: 2): يتضمن أسئلة مباشرة أو أسئلة متعددة الاختيارات مرتبطة بمجال الصحة العامة. 2. اختبار تطبيقي (المدة: ساعتان، المعامل: 3): يتضمن أسئلة مباشرة أو أسئلة متعددة الاختيارات مرتبطة بالتخصصات المطلوبة، بهدف تقييم مدى قدرة المترشح على القيام بالمهام المرتبطة بالدرجة المتبارى بشأنها. تمنح عن الاختبارين نقطة عددية تتراوح ما بين 0 و20، وتعتبر إقصائية كل نقطة تساوي أو تقل عن 5 من 20. تحصر لائحة المترشحين الناجحين في حدود عدد المناصب المتبارى بشأنها، من بين الحاصلين على معدل عام لا يقل عن 10 من 20، دون الحصول على نقطة إقصائية.",
  apresTest: "تنشر لوائح المترشحين المقبولين على الموقع الإلكتروني للوزارة (www.sante.gov.ma) وعلى موقع www.emploi-public.ma. تعتبر هذه اللوائح بمثابة استدعاء رسمي. بعد اجتياز الاختبارين، تعلن لوائح الناجحين النهائيين مرتبين حسب الاستحقاق في حدود المناصب المتبارى بشأنها. يعين المترشحون الناجحون بالنفوذ الترابي للمديرية الجهوية للصحة والحماية الاجتماعية بجهة درعة تافيلالت.",
