  "introText": "تعلن وزارة الصحة والحماية الاجتماعية بشكل رسمي عن فتح باب الترشيح لإجراء مباراة كبرى لتوظيف 100 تقني من الدرجة الرابعة (سلم 8) لعام 2026، وهي خطوة استراتيجية هامة تهدف إلى دعم الموارد البشرية وتجويد الخدمات الصحية داخل المصالح المركزية والمؤسسات الاستشفائية التابعة لها عبر ربوع المملكة. تكتسي هذه المباراة أهمية استثنائية نظراً لطبيعة التخصصات الطبية والاجتماعية الدقيقة المطلوبة، والتي تمس بشكل مباشر السير اليومي للمستشفيات وتدبير الأزمات الصحية بالمركبات الجراحية وأقسام المستعجلات. إن فتح هذه المناصب يعكس التزام الدولة بتسريع وتيرة إصلاح المنظومة الصحية الوطنية وتوفير فرص شغل حقيقية ومستقرة للشباب الخريجين من معاهد التكوين المهني في الميدان الصحي، مما يمنحهم منصة مثالية لبناء مسار مهني واعد والمساهمة الفعالة في إنجاح ورش الحماية الاجتماعية الملكي وتطوير جودة الرعاية الطبية المقدمة للمواطنين المغاربة.",
