  "centreMabara": "تجرى المباراة بالمراكز التالية: الرباط، الدار البيضاء، فاس، تطوان، وجدة، بني ملال، مراكش، أكادير، كلميم، الرشيدية، العيون، ووادي الذهب.",
  "epreuves": "تشتمل المباراة على مرحلتين من الاختبارات: أولاً: اختبارات كتابية وتضم: أ) اختبار يتعلق بالتخصص المتبارى بشأن يطابق مستوى درجة تقني من الدرجة الرابعة (المدة: 3 ساعات، المعامل: 3). ب) اختبار عام في التحليل والترجمة يتضمن تلخيص نص باللغة العربية أو الفرنسية والتعليق عليه ثم ترجمة الملخص إلى اللغتين (المدة: 3 ساعات، المعامل: 2). وتعتبر إقصائية كل نقطة تقل عن 5 من 20 في أي اختبار كتابي، ويتأهل للشفوي من حصل على معدل لا يقل عن 12 من 20. ثانياً: اختبار شفوي يتعلق بالثقافة العامة وبالتخصص المتبارى بشأنه (المدة: 15 دقيقة على الأقل، المعامل: 2).",
