  "introText": "في إطار تعزيز مواردها البشرية بكفاءات عليا قادرة على مواكبة التطورات الإدارية والرقمية، أعلنت وزارة الشباب والثقافة والتواصل - قطاع التواصل عن تنظيم مباراة هامة لتوظيف 19 متصرفاً من الدرجة الثانية (سلم 11)[span_0](start_span)[span_0](end_span). تأتي هذه المبادرة لضخ دماء جديدة في شرايين الإدارة المركزية بالرباط، استجابة للتحديات الكبرى التي يواجهها القطاع في مجالات التواصل المؤسساتي، التدبير المالي، والمواكبة التشريعية[span_1](start_span)[span_1](end_span). يعتبر منصب متصرف من الدرجة الثانية من المناصب الاستراتيجية في هرم الوظيفة العمومية، حيث يعول على هؤلاء الأطر للمساهمة في صنع القرار وتنزيل السياسات العمومية بكفاءة وفعالية. تمثل هذه المباراة فرصة ذهبية لحاملي شهادة الماستر والديبلومات العليا في تخصصات دقيقة ومتنوعة لبناء مسار مهني متميز داخل قطاع حيوي يلعب دوراً محورياً في إشعاع المملكة تواصلياً وثقافياً. إن ولوج هذا المنصب يتطلب استعداداً فكرياً ومهنياً عالياً نظراً لثقل المسؤوليات الملقاة على عاتق المتصرفين في تدبير الشأن العام وتحديث الإدارة المغربية.",
