  "introText": "أعلنت وزارة النقل واللوجيستيك عن تنظيم مباراة لتوظيف 25 متصرفاً من الدرجة الثالثة (السلم 10) في تخصصي القانون العام والقانون الخاص. تأتي هذه المباراة في إطار تعزيز قدرات الوزارة بالموارد البشرية المؤهلة، لمواكبة الإصلاحات الهيكلية الكبرى التي يعرفها قطاع النقل واللوجيستيك بالمغرب. وتُعتبر المباراة فرصة استثنائية لحاملي شهادة الإجازة في القانون الراغبين في ولوج الوظيفة العمومية والاستفادة من الاستقرار المهني الذي توفره. ستجرى الاختبارات الكتابية يوم 12 يوليوز 2026 بمدينة الرباط، على أن يتم الترشيح حصراً عبر بوابة التشغيل العمومي إلى غاية 23 يونيو 2026.",
