  "epreuves": "تشتمل المباراة على اختبارين رئيسيين:\n\n1. الاختبار الكتابي (3 ساعات، المعامل 3): يتضمن موضوعاً أو أسئلة ذات اختيارات متعددة (QCM) في مجال التدبير العمومي، أو التخصصات المطلوبة، أو المهام المرتبطة بالوظيفة.\n2. الاختبار الشفوي (بين 15 و30 دقيقة، المعامل 3): مقابلة تناقش فيها لجنة المباراة مع المترشح قضايا ومواضيع مختلفة بهدف تقييم مدى قدرته على ممارسة المهام المرتبطة بدرجة متصرف.",
