  "carriere": "يعتبر منصب متصرف من الدرجة الثالثة (السلم 10) مدخلاً أساسياً لمسار مهني واعد داخل الوزارة. بعد سنتين من التعيين، يتم ترسيم الموظف. وبعد 6 سنوات من الخدمة الفعلية، يمكنه الترقية إلى درجة متصرف من الدرجة الثانية (السلم 11). ومع اكتساب الخبرة واجتياز المباريات المهنية الداخلية، يمكنه بلوغ منصب رئيس مصلحة أو رئيس قسم. توفر وزارة النقل واللوجيستيك تكويناً مستمراً في مجالات الحوكمة، الصفقات العمومية، والقانون الجوي والبحري، مما يفتح آفاقاً واسعة للانتقال إلى مناصب عليا داخل القطاعين العام والخاص."
