  "introText": "أعلنت وزارة الصحة والحماية الاجتماعية عن تنظيم مباراة لتوظيف 300 ممرض من الدرجة الأولى (السلم 10) بجهة الدار البيضاء-سطات، وذلك يوم 12 يوليوز 2026. تأتي هذه المباراة في إطار تعزيز المنظومة الصحية الوطنية وتأهيل الموارد البشرية العاملة في القطاع الصحي، تماشياً مع أجرأة مشروع الحماية الاجتماعية وتعميم التغطية الصحية. وتُعد وزارة الصحة والحماية الاجتماعية المؤسسة السيادية المكلفة بتنفيذ السياسة الوطنية للصحة، وضمان ولوج كافة المواطنين لعلاجات ذات جودة متميزة، مما يجعل هذه المباراة فرصة ذهبية لحاملي دبلوم التمريض الراغبين في الاستقرار المهني والمساهمة في خدمة الوطن.[reference:0][reference:1]",
  "description": "وزارة الصحة والحماية الاجتماعية تعلن عن مباراة لتوظيف 300 ممرض من الدرجة الأولى (سلم 10) بجهة الدار البيضاء-سطات.",
  "mission": "يتولى الممرضون من الدرجة الأولى مهامًا صحية وعلاجية متعددة تشمل: تقديم الرعاية التمريضية للمرضى في المؤسسات الاستشفائية، متابعة حالتهم الصحية وتقييمها، تنفيذ الوصفات الطبية ومراقبة فعاليتها، المشاركة في برامج التوعية الصحية والوقاية، تدبير الطوارئ الطبية والإسعافات الأولية، المساهمة في التكوين المستمر للأطر المساعدة، وضمان جودة الخدمات الصحية المقدمة وفق المعايير الوطنية والدولية.[reference:2]",
  "lieu": "المؤسسات الاستشفائية التابعة للنفوذ الترابي لجهة الدار البيضاء-سطات.[reference:3]",
  "ageLimit": "ما بين 18 و45 سنة كحد أقصى عند فاتح يناير من السنة الجارية.[reference:4]",
  "diplome": "دبلوم الإجازة في التمريض مسلم من المعهد العالي للمهن التمريضية وتقنيات الصحة (ISPITS)، أو دبلوم الدولة للطور الأول للدراسات شبه الطبية، أو إحدى الشهادات المعادلة لها طبقاً للمقتضيات النظامية الجاري بها العمل.[reference:5]",
  "specialites": "التمريض – الصحة والطب[reference:6]",
