  "epreuves": "تشتمل المباراة على اختبارين رئيسيين:\n\n1. الاختبار الكتابي: يتضمن موضوعاً عاماً أو أسئلة متعددة الاختيارات (QCM) في مجال التمريض والعلوم الصحية الأساسية، بهدف تقييم المعرفة النظرية للمترشحين.[reference:23]\n\n2. الاختبار الشفوي: مقابلة تناقش فيها لجنة المباراة مع المترشح مواضيع مختلفة في مجال التخصص، بهدف تقييم قدرته على ممارسة المهام المرتبطة بالدرجة المتبارى بشأنها.[reference:24]\n\nيُشترط للنجاح في الاختبار الكتابي الحصول على نقطة لا تقل عن 12 من 20 للتأهل إلى الاختبار الشفوي.[reference:25]",
  "apresTest": "تنشر نتائج الاختبار الكتابي والنتائج النهائية، بما في ذلك لائحة الانتظار، على بوابة التشغيل العمومي www.emploi-public.ma. يُشترط على الناجحين استكمال ملفاتهم بالوثائق الإدارية المطلوبة للتعيين بالوظيفة العمومية، وإلا سيتم تعويضهم بمترشحين من لائحة الانتظار حسب الترتيب والاستحقاق.[reference:26]",
