  "introText": "أعلنت وزارة الصحة والحماية الاجتماعية، ممثلة في المديرية الجهوية للصحة بجهة فاس-مكناس، عن تنظيم مباراة لتوظيف 390 ممرضاً وتقني صحة من الدرجة الأولى (السلم 10)، وذلك يوم 12 يوليوز 2026 بمدينة فاس[reference:0][reference:1]. تأتي هذه المباراة في إطار تعزيز المنظومة الصحية الوطنية وتأهيل الموارد البشرية العاملة في القطاع الصحي، تماشياً مع ورش الإصلاح الصحي الكبير الذي تشهده المملكة، خاصة مع تفعيل نظام المجموعات الصحية الترابية (GST) الذي يتطلب تعزيزاً كبيراً في الأطر التمريضية والتقنية[reference:2]. وتُعد وزارة الصحة والحماية الاجتماعية المؤسسة السيادية المكلفة بتنفيذ السياسة الوطنية للصحة، وضمان ولوج كافة المواطنين لعلاجات ذات جودة متميزة[reference:3]. تهدف هذه المباراة إلى سد الخصاص المسجل في المؤسسات الاستشفائية التابعة للنفوذ الترابي لجهة فاس-مكناس، وهي فرصة استثنائية لحاملي دبلوم التمريض وتقنيات الصحة الراغبين في الاستقرار المهني والمساهمة في خدمة الوطن[reference:4].",
  "description": "وزارة الصحة والحماية الاجتماعية تعلن عن مباراة لتوظيف 390 ممرضاً وتقني صحة من الدرجة الأولى (سلم 10) بجهة فاس-مكناس.",
  "mission": "يتولى الممرضون وتقنيو الصحة من الدرجة الأولى مهامًا صحية وعلاجية متعددة تشمل: تقديم الرعاية التمريضية للمرضى في المؤسسات الاستشفائية، متابعة حالتهم الصحية وتقييمها، تنفيذ الوصفات الطبية ومراقبة فعاليتها، المشاركة في برامج التوعية الصحية والوقاية، تدبير الطوارئ الطبية والإسعافات الأولية، المساهمة في التكوين المستمر للأطر المساعدة، وضمان جودة الخدمات الصحية المقدمة وفق المعايير الوطنية والدولية. كما تشمل المهام حسب التخصص: التوليد والأطفال، صحة الأسرة والصحة الجماعاتية، التخدير والإنعاش، أمراض الكلى وتصفية الدم، الترويض الطبي، التغذية، والإحصاء الصحي[reference:5].",
